//! `cargo xtask bindings [--check]` (backlog E9-S7, plan.md §10.1): generates `include/diffsync.h`
//! (cbindgen) and `bindings/csharp/NativeMethods.g.cs` (csbindgen) from `crates/core-ffi`. With
//! `--check` nothing is written and the command fails when a generated file is stale.

use std::path::{Path, PathBuf};

const HEADER_PATH: &str = "include/diffsync.h";
const CSHARP_PATH: &str = "bindings/csharp/NativeMethods.g.cs";
/// The modules that hold `extern "C"` exports.
const EXPORT_FILES: &[&str] = &[
    "lib.rs",
    "text.rs",
    "tools.rs",
    "edit.rs",
    "folder.rs",
    "sync.rs",
    "types.rs",
    "status.rs",
];

fn repo() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn normalise(s: &str) -> String {
    s.replace("\r\n", "\n")
}

fn header() -> Result<String, String> {
    let crate_dir = repo().join("crates").join("core-ffi");
    let config = cbindgen::Config {
        language: cbindgen::Language::C,
        include_guard: Some("DIFFSYNC_H".into()),
        no_includes: false,
        sys_includes: vec!["stdint.h".into(), "stddef.h".into()],
        header: Some(
            "/* diffsync_core C ABI. GENERATED by `cargo xtask bindings`; do not edit. See docs/abi.md. */"
                .into(),
        ),
        documentation: true,
        style: cbindgen::Style::Type,
        usize_is_size_t: true,
        ..cbindgen::Config::default()
    };
    let bindings = cbindgen::Builder::new()
        .with_crate(crate_dir)
        .with_config(config)
        .generate()
        .map_err(|e| format!("cbindgen failed: {e}"))?;
    let mut out = Vec::new();
    bindings.write(&mut out);
    Ok(normalise(&String::from_utf8_lossy(&out)))
}

fn csharp() -> Result<String, String> {
    let src = repo().join("crates").join("core-ffi").join("src");
    let tmp = std::env::temp_dir().join(format!("diffsync-csbindgen-{}.cs", std::process::id()));
    let mut b = csbindgen::Builder::default();
    for f in EXPORT_FILES {
        b = b.input_extern_file(src.join(f));
    }
    b.csharp_dll_name("diffsync_core")
        .csharp_namespace("DiffSync.Native")
        .csharp_class_name("NativeMethods")
        .csharp_class_accessibility("internal")
        .csharp_use_function_pointer(true)
        .generate_csharp_file(&tmp)
        .map_err(|e| format!("csbindgen failed: {e}"))?;
    let text = std::fs::read_to_string(&tmp).map_err(|e| e.to_string())?;
    let _ = std::fs::remove_file(&tmp);
    Ok(normalise(&text))
}

fn sync(path: &str, fresh: &str, check: bool) -> Result<(), String> {
    let full = repo().join(path);
    let old = std::fs::read_to_string(&full).ok().map(|s| normalise(&s));
    if old.as_deref() == Some(fresh) {
        println!("bindings: {path} is up to date");
        return Ok(());
    }
    if check {
        return Err(format!(
            "bindings: {path} is stale; run `cargo xtask bindings` and commit the result"
        ));
    }
    if let Some(dir) = full.parent() {
        std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
    }
    std::fs::write(&full, fresh).map_err(|e| format!("{path}: {e}"))?;
    println!("bindings: wrote {path}");
    Ok(())
}

pub fn run(check: bool) -> Result<(), String> {
    sync(HEADER_PATH, &header()?, check)?;
    sync(CSHARP_PATH, &csharp()?, check)
}
